import java.util.*;
import java.io.*;

public class Main {
    static final long BIG_INF = (long)1e9 + 9;
    static final long INF = Long.MAX_VALUE;
    static int n, m, T;
    static int s, t;
    static List<List<Integer>> adj;
    static List<Edge> edges;
    static String[] sci = new String[101];
    static String[] reac = new String[101];
    static int[][] turnsUnusable = new int[10][10];
    static int[][] visited = new int[101][101];

    static class Edge {
        int u, v;
        long flow, capacity;

        Edge(int u, int v, long flow, long capacity) {
            this.u = u;
            this.v = v;
            this.flow = flow;
            this.capacity = capacity;
        }
    }

    static class PairInt {
        int first, second;

        PairInt(int first, int second) {
            this.first = first;
            this.second = second;
        }
    }

    static class PairPi {
        PairInt first;
        int second;

        PairPi(PairInt first, int second) {
            this.first = first;
            this.second = second;
        }
    }

    static boolean validPos(int r, int c) {
        return r >= 0 && c >= 0 && r < n && c < m;
    }

    static int getID(int x, int y) {
        return 1 + m * x + y;
    }

    static void addEdge(int u, int v, long cap) {
        adj.get(u).add(edges.size());
        edges.add(new Edge(u, v, 0, cap));
        adj.get(v).add(edges.size());
        edges.add(new Edge(v, u, 0, 0));
    }

    static boolean bfs() {
        int size = adj.size();
        int[] dist = new int[size];
        Arrays.fill(dist, -1);
        dist[s] = 0;
        Queue<Integer> q = new LinkedList<>();
        q.offer(s);
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int id : adj.get(u)) {
                Edge e = edges.get(id);
                int v = e.v;
                if (dist[v] == -1 && e.flow < e.capacity) {
                    dist[v] = dist[u] + 1;
                    q.offer(v);
                    if (v == t) return true;
                }
            }
        }
        return false;
    }

    static long dfs(int u, long flow, int[] ptr, int[] dist) {
        if (flow == 0 || u == t) return flow;
        for (; ptr[u] < adj.get(u).size(); ++ptr[u]) {
            int id = adj.get(u).get(ptr[u]);
            Edge e = edges.get(id);
            int v = e.v;
            if (dist[v] == dist[u] + 1 && e.flow < e.capacity) {
                long pushed = dfs(v, Math.min(flow, e.capacity - e.flow), ptr, dist);
                if (pushed > 0) {
                    e.flow += pushed;
                    edges.get(id ^ 1).flow -= pushed;
                    return pushed;
                }
            }
        }
        return 0;
    }

    static long maxFlow() {
        long total = 0;
        while (true) {
            int[] dist = new int[adj.size()];
            Arrays.fill(dist, -1);
            if (!bfs()) break;
            int[] ptr = new int[adj.size()];
            while (true) {
                long pushed = dfs(s, INF, ptr, dist);
                if (pushed == 0) break;
                total += pushed;
            }
        }
        return total;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int T_input = Integer.parseInt(br.readLine());
        T = T_input + 1;
        n = m = Integer.parseInt(br.readLine());
        s = 0;
        t = m * m * 2 + 1;
        adj = new ArrayList<>();
        for (int i = 0; i <= t; i++) {
            adj.add(new ArrayList<>());
        }
        edges = new ArrayList<>();
        for (int i = 0; i < 101; i++) {
            sci[i] = br.readLine();
        }
        for (int i = 0; i < 101; i++) {
            reac[i] = br.readLine();
        }
        for (int i = 0; i < n; i++) {
            Arrays.fill(turnsUnusable[i], (int) BIG_INF);
        }
        // BFS for 'Z'
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (reac[i].charAt(j) == 'Z') {
                    Queue<PairInt> q = new LinkedList<>();
                    q.offer(new PairInt(i, j));
                    turnsUnusable[i][j] = 1;
                    while (!q.isEmpty()) {
                        PairInt p = q.poll();
                        int x = p.first, y = p.second;
                        for (int dx = -1; dx <= 1; dx++) {
                            for (int dy = -1; dy <= 1; dy++) {
                                if (Math.abs(dx) + Math.abs(dy) == 1) {
                                    int nx = x + dx, ny = y + dy;
                                    if (validPos(nx, ny) && turnsUnusable[nx][ny] == (int) BIG_INF && sci[nx].charAt(ny) != 'Y') {
                                        turnsUnusable[nx][ny] = turnsUnusable[x][y] + 1;
                                        q.offer(new PairInt(nx, ny));
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
        // Build graph
        for (int x = 0; x < n; x++) {
            for (int y = 0; y < m; y++) {
                char sciChar = sci[x].charAt(y);
                char reacChar = reac[x].charAt(y);
                if (sciChar >= '1' && sciChar <= '9') {
                    addEdge(s, getID(x, y), sciChar - '0');
                }
                if (reacChar >= '1' && reacChar <= '9') {
                    addEdge(n * n + getID(x, y), t, reacChar - '0');
                }
                for (int X = 0; X < n; X++) {
                    for (int Y = 0; Y < m; Y++) {
                        if (sciChar == 'Y' || sciChar == 'Z' || reac[X].charAt(Y) == 'Y' || reac[X].charAt(Y) == 'Z') continue;
                        for (int xx = 0; xx < 101; xx++) {
                            Arrays.fill(visited[xx], 0);
                        }
                        Queue<PairPi> q = new LinkedList<>();
                        q.offer(new PairPi(new PairInt(x, y), 1));
                        visited[x][y] = 1;
                        boolean reached = false;
                        while (!q.isEmpty()) {
                            PairPi p = q.poll();
                            int xx = p.first.first, yy = p.first.second, tStep = p.second;
                            if (xx == X && yy == Y) {
                                visited[xx][yy] = 1;
                                reached = true;
                                break;
                            }
                            if (tStep >= turnsUnusable[xx][yy] || tStep >= T) continue;
                            for (int dx = -1; dx <= 1; dx++) {
                                for (int dy = -1; dy <= 1; dy++) {
                                    if (Math.abs(dx) + Math.abs(dy) == 1) {
                                        int nx = xx + dx, ny = yy + dy;
                                        if (validPos(nx, ny) && visited[nx][ny] == 0 && sci[nx].charAt(ny) != 'Y' && sci[nx].charAt(ny) != 'Z' && tStep + 1 <= turnsUnusable[nx][ny]) {
                                            visited[nx][ny] = 1;
                                            q.offer(new PairPi(new PairInt(nx, ny), tStep + 1));
                                        }
                                    }
                                }
                            }
                        }
                        if (visited[X][Y] == 1) {
                            addEdge(getID(x, y), n * n + getID(X, Y), (long) BIG_INF);
                        }
                    }
                }
            }
        }
        long maxFlowVal = maxFlow();
        System.out.println(maxFlowVal);
    }
}

